function suffixOptionsHtmlForContractNumber(number, selected) { const record = state.contractInfo.find((item) => item.number === number); const suffixes = record?.suffixes || []; return '<option value="">Select suffix</option>' + suffixes.map((suffix) => `<option value="${esc(suffix.letter)}" ${suffix.letter === selected ? 'selected' : ''}>${esc(suffix.letter)}</option>`).join(''); }
