function refreshContractDerivedFields() { const record = state.contractInfo.find((item) => item.number === $('#contract-number').value); $('#contract-machine-type').value = record?.machineType || ''; const suffix = record?.suffixes.find((item) => item.letter === $('#contract-suffix').value); $('#contract-suffix-description').value = suffix?.description || ''; }
function openContractModal(contractId = null, prefill = {}) { editingContractId = contractId; const contract = contractId ? state.contracts.find((item) => item.id === contractId) : null; $('#contract-modal-title').textContent = contract ? 'Change image' : 'Add tile'; $('#contract-submit').innerHTML = contract ? 'Save changes' : '<span>+</span> Add tile'; $('#contract-customer-name').innerHTML = customerOptionsHtml(contract?.customerName || ''); $('#contract-number').innerHTML = contractNumberOptionsHtml(contract?.number || prefill.number || ''); refreshContractSuffixOptions(contract?.suffix || prefill.suffix || ''); $('#contract-suffix-description').value = contract?.suffixDescription || ''; $('#contract-machine-type').value = contract?.machineType || ''; if (!contract && prefill.number) refreshContractDerivedFields(); /* Edit tile changes the image only: the details come from Contract information */ const editing = Boolean(contract); $('#contract-linked-hint').classList.toggle('is-hidden', !editing); $('#contract-linked-hint').textContent = editing ? `${contract.number}${contract.suffix ? ` ${contract.suffix}` : ''} | ${contract.customerName}. To change the contract number, suffix or customer, use Contract information.` : ''; $('#contract-detail-fields').classList.toggle('is-hidden', editing); ['#contract-customer-name', '#contract-number', '#contract-suffix'].forEach((id) => { $(id).disabled = editing; }); $('#contract-image').value = ''; contractImageChoice = contract?.imageId || null; renderContractImagePicker(); loadImageLibrary(); $('#contract-modal').classList.remove('is-hidden'); (editing ? $('#contract-image') : $('#contract-customer-name')).focus(); }
/* Change image / Add tile: the tile's picture comes from the picture library. Pick one, or upload a new one
 * (shrunk here first, then added to the library); Remove image from tile leaves the tile without one. Nothing changes
 * on the tile until Save, so closing the form keeps its picture. A picture no tile uses can be deleted. */
let contractImageChoice = null;
let imageLibrary = [];
async function loadImageLibrary() { try { imageLibrary = await api('GET', '/api/images'); } catch (error) { showToast(`Could not load the pictures: ${error.message}`); } renderContractImagePicker(); }
function renderContractImagePicker() {
  const chosen = contractImageChoice;
  $('#contract-image-preview').innerHTML = chosen ? `<img src="${esc(imageUrl(chosen))}" alt="Chosen picture"><span>${esc(imageLibrary.find((item) => item.id === chosen)?.name || 'Chosen picture')}</span><button class="image-preview-action" id="contract-image-remove" type="button">Remove image from tile</button>` : '<span>No picture: choose one below or upload a new one.</span>';
  $('#image-library').innerHTML = imageLibrary.length ? imageLibrary.map((item) => `<li><button class="image-library-item ${item.id === chosen ? 'is-chosen' : ''}" data-image-id="${esc(item.id)}" type="button" title="${esc(item.name || 'Picture')}${item.tiles ? ` (on ${item.tiles} ${item.tiles === 1 ? 'tile' : 'tiles'})` : ' (not on any tile)'}" aria-pressed="${item.id === chosen}"><img src="${esc(imageUrl(item.id))}" alt="${esc(item.name || 'Picture')}" loading="lazy"></button>${item.tiles || item.id === chosen ? '' : `<button class="image-library-delete" data-delete-image="${esc(item.id)}" type="button" title="Delete this picture" aria-label="Delete this picture">${X_CIRCLE}</button>`}</li>`).join('') : '<li class="image-library-empty">No pictures yet.</li>';
}
// Shrink to 1280px at most each way and save as JPEG on white, so a picture is about 100-200 KB.
async function shrinkImage(file) { const bitmap = await createImageBitmap(file); const scale = Math.min(1, 1280 / bitmap.width, 1280 / bitmap.height); const width = Math.round(bitmap.width * scale); const height = Math.round(bitmap.height * scale); const canvas = document.createElement('canvas'); canvas.width = width; canvas.height = height; const ctx = canvas.getContext('2d'); ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, width, height); ctx.drawImage(bitmap, 0, 0, width, height); bitmap.close(); return { dataUrl: canvas.toDataURL('image/jpeg', 0.85), width, height }; }
async function uploadContractImage() { const input = $('#contract-image'); const file = input.files[0]; if (!file) return; const status = $('#contract-image-status'); status.textContent = 'Uploading…'; try { const picture = await shrinkImage(file); const { id } = await api('POST', '/api/images', { ...picture, name: file.name.replace(/\.[^.]+$/, '') }); contractImageChoice = id; await loadImageLibrary(); } catch (error) { showToast(`Could not upload the picture: ${error.message}`); } finally { status.textContent = ''; input.value = ''; } }
function deleteLibraryImage(id) { showConfirm('Delete this picture from the library?', 'Delete').then(async (confirmed) => { if (!confirmed) return; try { await api('DELETE', `/api/images/${encodeURIComponent(id)}`); await loadImageLibrary(); showToast('Picture deleted'); } catch (error) { showToast(error.message); } }); }
