function saveContract(event) { event.preventDefault(); const formData = new FormData(event.currentTarget); const linkedContract = editingContractId ? state.contracts.find((item) => item.id === editingContractId) : null; /* editing changes the image only (the detail fields are hidden), so keep the details */ const customerName = linkedContract ? linkedContract.customerName : formData.get('customerName').trim(); const number = linkedContract ? linkedContract.number : formData.get('number').trim(); const suffix = linkedContract ? linkedContract.suffix : formData.get('suffix').trim(); const suffixDescription = linkedContract ? linkedContract.suffixDescription : formData.get('suffixDescription').trim(); const machineType = linkedContract ? linkedContract.machineType : formData.get('machineType'); const imageId = contractImageChoice; const contractId = editingContractId; const finishSaveContract = () => { if (contractId) { const contract = state.contracts.find((item) => item.id === contractId); contract.customerName = customerName; contract.number = number; contract.suffix = suffix; contract.suffixDescription = suffixDescription; contract.machineType = machineType; contract.imageId = imageId; } else { const id = `contract-${Date.now()}`; state.contracts.push({ id, customerName, number, suffix, suffixDescription, machineType, imageId, activeSessions: {}, hidden: false }); state.order.push(id); } saveState(); renderContracts(); renderEditTimes(); if (!$('#find-tiles-modal').classList.contains('is-hidden')) renderFindTiles(); closeContractModal(); showToast(contractId ? 'Tile updated' : 'Tile added to dashboard'); }; const proceedWithSave = finishSaveContract; const isDuplicate = !contractId && state.contracts.some((item) => item.customerName === customerName && item.number === number && item.suffix === suffix); if (isDuplicate) { showConfirm('A tile for this customer, contract number and suffix already exists. Add it anyway?').then((confirmed) => { if (confirmed) proceedWithSave(); }); } else { proceedWithSave(); } }
function machineTypeOptionsHtml(selected) { return '<option value="">Select machine type</option>' + state.machineTypes.map((type) => `<option value="${esc(type)}" ${type === selected ? 'selected' : ''}>${esc(type)}</option>`).join(''); }
/* Manage lists: each list's "Add a…" box also filters its list as you type (every word must match, any capitals), so a name
 * that's already there shows up before it is added twice. A count and Clear show while filtering; switching tab clears it. */
const LIST_FILTERS = [['machine-type-input', 'machine-type-list'], ['suffix-description-input', 'suffix-description-list'], ['customer-input', 'customer-list'], ['cost-centre-input', 'cost-centre-list'], ['rework-reason-input', 'rework-reason-list']];
function filterList(inputId, listId) { const typed = $('#' + inputId).value.trim(); const words = typed.toLowerCase().split(/\s+/).filter(Boolean); const items = [...$('#' + listId).querySelectorAll('li:not(.list-empty)')]; let shown = 0; let exact = false; items.forEach((item) => { const text = item.textContent.trim().toLowerCase(); const match = words.every((word) => text.includes(word)); const same = Boolean(typed) && text === typed.toLowerCase(); item.classList.toggle('is-hidden', !match); item.classList.toggle('is-exact', same); if (match) shown += 1; if (same) exact = true; }); const status = document.querySelector(`[data-filter-status="${listId}"]`); status.classList.toggle('is-hidden', !words.length); status.querySelector('span').textContent = exact ? 'Already in the list' : shown ? `Showing ${shown} of ${items.length}` : 'Not in the list yet: + Add adds it'; }
function wireListFilters() { LIST_FILTERS.forEach(([inputId, listId]) => { const list = $('#' + listId); list.insertAdjacentHTML('beforebegin', `<div class="list-filter-status is-hidden" data-filter-status="${listId}"><span></span><button class="secondary-button" type="button">Clear</button></div>`); $('#' + inputId).addEventListener('input', () => filterList(inputId, listId)); list.previousElementSibling.querySelector('button').addEventListener('click', () => { $('#' + inputId).value = ''; filterList(inputId, listId); $('#' + inputId).focus(); }); new MutationObserver(() => filterList(inputId, listId)).observe(list, { childList: true }); /* a re-drawn list keeps the filter */ $('#' + inputId).form.addEventListener('submit', () => setTimeout(() => filterList(inputId, listId))); /* + Add empties the box: show the whole list again */ }); }
function clearListFilters() { LIST_FILTERS.forEach(([inputId, listId]) => { $('#' + inputId).value = ''; filterList(inputId, listId); }); }
function switchListTab(tabId) { clearListFilters(); document.querySelectorAll('.modal-tab').forEach((tab) => tab.classList.toggle('is-active', tab.dataset.listTab === tabId)); document.querySelectorAll('[data-list-panel]').forEach((panel) => panel.classList.toggle('is-hidden', panel.dataset.listPanel !== tabId)); }
function openListsModal(tabId = 'machine-type') { $('#lists-modal').classList.remove('is-hidden'); document.querySelectorAll('.modal-tab[data-admin-only]').forEach((tab) => tab.classList.toggle('is-hidden', !(isAdmin() || (isManager() && 'managerOk' in tab.dataset)))); /* Users and Cost centre are company-wide settings: admins only */ switchListTab(tabId); renderMachineTypeList(); renderSuffixDescriptionList(); renderCustomerList(); renderUserList(); renderCostCentreList(); renderReworkReasonList(); patternDraft = null; setPatternDirty(false); renderWorkingPatterns(); $('#default-wt-delay').value = state.autoClockOutDelay ?? 120; renderAutoClockOutDelay(); if (managesPeople()) loadDirectory(); }
function goToContractInformation() { closeContractModal(); $('#nav-setup-children').classList.remove('is-hidden'); $('#nav-setup-toggle').setAttribute('aria-expanded', 'true'); $('#nav-setup-toggle').classList.add('is-expanded'); document.querySelector('[data-view="contract-information"]').click(); showToast('Add or edit the missing details, then reopen Add tile'); }
function enableFieldLongPress(selector, callback) { const element = $(selector); if (!element) return; let pressTimer; const cancelPress = () => clearTimeout(pressTimer); element.addEventListener('pointerdown', () => { pressTimer = setTimeout(callback, 700); }); element.addEventListener('pointerup', cancelPress); element.addEventListener('pointerleave', cancelPress); element.addEventListener('pointercancel', cancelPress); element.addEventListener('change', cancelPress); element.addEventListener('blur', cancelPress); }
function closeListsModal() { $('#lists-modal').classList.add('is-hidden'); $('#machine-type-input').value = ''; $('#suffix-description-input').value = ''; $('#customer-input').value = ''; $('#cost-centre-input').value = ''; if (!$('#contract-modal').classList.contains('is-hidden')) { const customerSelect = $('#contract-customer-name'); customerSelect.innerHTML = customerOptionsHtml(customerSelect.value); } }
function levenshteinDistance(a, b) { const rows = a.length + 1; const cols = b.length + 1; const dp = Array.from({ length: rows }, () => new Array(cols).fill(0)); for (let i = 0; i < rows; i += 1) dp[i][0] = i; for (let j = 0; j < cols; j += 1) dp[0][j] = j; for (let i = 1; i < rows; i += 1) { for (let j = 1; j < cols; j += 1) { dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]); } } return dp[rows - 1][cols - 1]; }
function textSimilarity(a, b) { const distance = levenshteinDistance(a.toLowerCase(), b.toLowerCase()); const maxLength = Math.max(a.length, b.length) || 1; return 1 - distance / maxLength; }
function findSimilarEntry(value, list, threshold = 0.75) { let best = null; let bestScore = 0; list.forEach((item) => { const score = textSimilarity(value, item); if (score > bestScore) { bestScore = score; best = item; } }); return bestScore >= threshold ? best : null; }
function renderSuffixDescriptionList() { const list = $('#suffix-description-list'); list.innerHTML = state.suffixDescriptions.length ? state.suffixDescriptions.map((desc) => `<li>${esc(desc)}<button class="remove-list-item" data-suffix-desc="${esc(desc)}" type="button" aria-label="Remove ${esc(desc)}"${isAdmin() ? '' : ` disabled title="${ADMIN_ONLY_REMOVE}"`}>${X_CIRCLE}</button></li>`).join('') : '<li class="list-empty">No suffix descriptions yet.</li>'; list.querySelectorAll('.remove-list-item').forEach((button) => button.addEventListener('click', () => removeSuffixDescription(button.dataset.suffixDesc))); }
function addSuffixDescription(event) { event.preventDefault(); const input = $('#suffix-description-input'); const value = sentenceCase(input.value); if (!value) return; const exactMatch = state.suffixDescriptions.find((item) => item.toLowerCase() === value.toLowerCase()); if (exactMatch) { showToast('That suffix description already exists'); input.value = ''; return; } const commit = () => { state.suffixDescriptions = sortNames([...state.suffixDescriptions, value]); input.value = ''; saveState(); renderSuffixDescriptionList(); renderContractInfo(); }; const similar = findSimilarEntry(value, state.suffixDescriptions); if (similar) { showConfirm(`This looks similar to "${similar}". Add it anyway?`).then((confirmed) => { if (confirmed) commit(); }); } else { commit(); } }
