function addMachineType(event) { event.preventDefault(); const input = $('#machine-type-input'); const value = upperCase(input.value); if (!value || state.machineTypes.some((item) => item.toLowerCase() === value.toLowerCase())) { if (value) showToast('That machine type is already in the list'); input.value = ''; return; } state.machineTypes = sortNames([...state.machineTypes, value]); input.value = ''; saveState(); renderMachineTypeList(); renderContractInfo(); }
function removeMachineType(type) { state.machineTypes = state.machineTypes.filter((item) => item !== type); saveState(); renderMachineTypeList(); renderContractInfo(); }
function renderCustomerList() { const list = $('#customer-list'); list.innerHTML = state.customers.length ? state.customers.map((name) => `<li>${esc(name)}<button class="remove-list-item" data-customer="${esc(name)}" type="button" aria-label="Remove ${esc(name)}"${isAdmin() ? '' : ` disabled title="${ADMIN_ONLY_REMOVE}"`}>${X_CIRCLE}</button></li>`).join('') : '<li class="list-empty">No customers yet.</li>'; list.querySelectorAll('.remove-list-item').forEach((button) => button.addEventListener('click', () => removeCustomer(button.dataset.customer))); }
function addCustomer(event) { event.preventDefault(); const input = $('#customer-input'); const value = titleCase(input.value); if (!value || state.customers.some((item) => item.toLowerCase() === value.toLowerCase())) { if (value) showToast('That customer is already in the list'); input.value = ''; return; } state.customers = sortNames([...state.customers, value]); input.value = ''; saveState(); renderCustomerList(); renderContractInfo(); }
function removeCustomer(name) { state.customers = state.customers.filter((item) => item !== name); saveState(); renderCustomerList(); renderContractInfo(); }
// Cost centres (admins), always A-Z. Click a name to rename it: the server renames it for everyone who has it too. The × only deletes one nobody has.
const sortNames = (names) => [...names].sort((a, b) => a.localeCompare(b, 'en', { sensitivity: 'base' }));
function renderCostCentreList() { const list = $('#cost-centre-list'); list.innerHTML = state.costCentres.length ? sortNames(state.costCentres).map((name) => `<li><button class="list-item-name" data-rename-cost-centre="${esc(name)}" type="button" title="Click to rename">${esc(name)}</button><button class="remove-list-item" data-cost-centre="${esc(name)}" type="button" aria-label="Remove ${esc(name)}">${X_CIRCLE}</button></li>`).join('') : '<li class="list-empty">No cost centres yet.</li>'; list.querySelectorAll('.remove-list-item').forEach((button) => button.addEventListener('click', () => removeCostCentre(button.dataset.costCentre))); list.querySelectorAll('[data-rename-cost-centre]').forEach((button) => button.addEventListener('click', () => startCostCentreRename(button))); }
function startCostCentreRename(button) { const from = button.dataset.renameCostCentre; const input = document.createElement('input'); input.type = 'text'; input.className = 'list-item-rename'; input.value = from; input.maxLength = 100; input.setAttribute('aria-label', `Rename ${from}`); button.replaceWith(input); input.focus(); input.select(); let done = false; const finish = (save) => { if (done) return; done = true; const to = sentenceCase(input.value); if (save && to && to !== from) renameCostCentre(from, to); else renderCostCentreList(); }; input.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); finish(true); } else if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); finish(false); } }); input.addEventListener('blur', () => finish(true)); }
// The server changed the list (and maybe people): take its copy as saved, so saveState does not send it again.
