function addReworkReason(event) { event.preventDefault(); const input = $('#rework-reason-input'); const value = sentenceCase(input.value); input.value = ''; if (!value || (state.reworkReasons || []).some((name) => name.toLowerCase() === value.toLowerCase())) return; state.reworkReasons = sortNames([...(state.reworkReasons || []), value]); saveState(); renderReworkReasonList(); }
function removeReworkReason(name) { state.reworkReasons = state.reworkReasons.filter((item) => item !== name); Object.keys(reworkArmed).forEach((key) => { if (reworkArmed[key] === name) delete reworkArmed[key]; }); saveState(); renderReworkReasonList(); renderContracts(); }
// The (+) beside a table heading (Users -> Cost centre, Reference contracts -> Machine type and Customer name):
// type a new entry right there without opening Manage lists. Enter adds, Esc or clicking away cancels.
/* The name lists keep one style whatever is typed: machine types in capitals, customers in title case, suffix descriptions,
 * cost centres and rework reasons in sentence case. A word typed all in capitals (an acronym such as RFU) is kept, unless the
 * whole name was typed in capitals. The server applies the same rules (src/utils/textCase.js). */
const tidyName = (text) => String(text ?? '').trim().replace(/\s+/g, ' ');
const isAcronym = (word, allCaps) => !allCaps && /[A-Z].*[A-Z]/.test(word) && word === word.toUpperCase();
const typedInCapitals = (text) => text.includes(' ') && text === text.toUpperCase() && /[A-Z]/.test(text);
const upperCase = (text) => tidyName(text).toUpperCase();
function sentenceCase(text) { const clean = tidyName(text); const allCaps = typedInCapitals(clean); return clean.split(' ').map((word, index) => { if (isAcronym(word, allCaps)) return word; const lower = word.toLowerCase(); return index === 0 ? lower.charAt(0).toUpperCase() + lower.slice(1) : lower; }).join(' '); }
function titleCase(text) { const clean = tidyName(text); const allCaps = typedInCapitals(clean); return clean.split(' ').map((word) => (isAcronym(word, allCaps) ? word : word.toLowerCase().replace(/(^|[^a-z0-9])([a-z])/g, (match, before, letter) => before + letter.toUpperCase()))).join(' '); }
const NAME_CASE = { machineType: upperCase, customer: titleCase, suffixDescription: sentenceCase, costCentre: sentenceCase };
const HEADING_ADDS = {
  costCentre: { placeholder: 'New cost centre', add: addCostCentreName, added: (value) => `${value} added — pick it in anyone's Cost centre box` },
  machineType: { placeholder: 'New machine type', add: (value) => addNameToList('machineTypes', value), added: (value) => `${value} added — pick it in the Machine type box` },
  customer: { placeholder: 'New customer', add: (value) => addNameToList('customers', value), added: (value) => `${value} added — pick it in the Customer name box` },
  suffixDescription: { placeholder: 'New suffix description', add: (value) => addNameToList('suffixDescriptions', value), added: (value) => `${value} added — pick it in a suffix's Description box` },
};
// Every list in Manage lists is kept A-Z (the server also sends them A-Z).
function addNameToList(key, value) { if (!value || state[key].some((name) => name.toLowerCase() === value.toLowerCase())) return false; state[key] = sortNames([...state[key], value]); saveState(); renderMachineTypeList(); renderSuffixDescriptionList(); renderCustomerList(); renderContractInfo(); return true; }
function startHeadingAdd(button) {
  const kind = HEADING_ADDS[button.dataset.headingAdd]; const heading = button.closest('.th-with-action'); if (!kind || !heading || heading.querySelector('input')) return;
  const label = heading.innerHTML; const input = document.createElement('input'); input.type = 'text'; input.className = 'th-add-input'; input.placeholder = kind.placeholder; input.maxLength = 100; input.setAttribute('aria-label', kind.placeholder);
  heading.replaceChildren(input); input.focus();
  let done = false;
  const finish = (save) => { if (done) return; done = true; const value = (NAME_CASE[button.dataset.headingAdd] || tidyName)(input.value); heading.innerHTML = label; if (!save || !value) return; showToast(kind.add(value) ? kind.added(value) : `${value} is already in the list`); };
  input.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); finish(true); } else if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); finish(false); } });
  input.addEventListener('blur', () => finish(false));
}
async function removeCostCentre(name) { try { applyCostCentres((await api('DELETE', `/api/cost-centres/${encodeURIComponent(name)}`)).costCentres); showToast(`${name} deleted`); } catch (error) { showToast(error.message); } }
function userTypeOptionsHtml(selected) { return ['admin', 'manager', 'user'].map((type) => `<option value="${type}" ${type === selected ? 'selected' : ''}>${type.charAt(0).toUpperCase() + type.slice(1)}</option>`).join(''); }
function costCentreOptionsHtml(selected) { return '<option value="">Select cost centre</option>' + sortNames(state.costCentres).map((name) => `<option value="${esc(name)}" ${name === selected ? 'selected' : ''}>${esc(name)}</option>`).join(''); }
// Lists -> Users. Admins see everyone from Microsoft Entra ID (/api/directory) and tick who is in Time Slide; everyone else sees the people already in it.
