function renderPatternTabs() { $('#pattern-day-tabs').innerHTML = WEEK_ORDER.map((weekday) => patternDraft.days[weekday - 1]).map((day) => { /* shown Sunday first; Monday is still the day the others can follow */ const monday = patternDraft.days[0]; const what = day.mode === 'off' ? 'not a working day' : day.mode === 'same' ? `same as Monday (${monday.start}–${monday.end})` : `${day.start}–${day.end}`; return `<button class="day-tab${day.weekday === patternDayShown ? ' is-active' : ''}${day.mode === 'off' ? ' is-off' : ''}" data-weekday="${day.weekday}" type="button" role="tab" aria-selected="${day.weekday === patternDayShown}" title="${WEEKDAYS[day.weekday - 1]}: ${what}">${DAY_SHORT[day.weekday - 1]}${day.mode === 'own' && day.weekday !== 1 ? '<i class="day-tab-dot" aria-label="own times"></i>' : ''}</button>`; }).join(''); }
function renderPatternDay() { const day = patternDraft.days[patternDayShown - 1]; const monday = patternDraft.days[0]; const modes = day.weekday === 1 ? '<p class="pattern-day-note">Every day set to Same as Monday uses these times.</p>' : `<div class="pattern-modes" role="radiogroup" aria-label="${WEEKDAYS[day.weekday - 1]}">${[['same', 'Same as Monday'], ['own', 'Own times'], ['off', 'Not a working day']].map(([mode, label]) => `<label class="pattern-mode${day.mode === mode ? ' is-active' : ''}"><input type="radio" name="pattern-mode" value="${mode}" ${day.mode === mode ? 'checked' : ''}>${label}</label>`).join('')}</div>`; const body = day.mode === 'own' ? `<div class="form-row"><label>Work starts<input type="time" data-pattern-field="start" value="${esc(day.start)}"></label><label>Work ends<input type="time" data-pattern-field="end" value="${esc(day.end)}"></label></div>${day.breaks.map((brk, index) => `<div class="form-row break-row"><label>Break starts<input type="time" data-break-index="${index}" data-break-field="start" value="${esc(brk.start)}"></label><label>Break ends<input type="time" data-break-index="${index}" data-break-field="end" value="${esc(brk.end)}"></label><button class="break-row-action remove-break-row" data-break-index="${index}" type="button" title="Remove this break" aria-label="Remove this break">${X_CIRCLE}</button></div>`).join('')}${day.breaks.length ? '' : '<p class="break-rows-empty">No breaks.</p>'}` : day.mode === 'same' ? `<p class="pattern-day-note">${esc(monday.start)}–${esc(monday.end)}, ${esc(breakListText(monday.breaks))}, as on Monday. Changing Monday changes this day too.</p>` : '<p class="pattern-day-note">No working hours or breaks. A clock left running stops at Monday\'s auto clock-out time.</p>'; $('#pattern-day').innerHTML = modes + body; $('#pattern-add-break').classList.toggle('is-hidden', day.mode !== 'own'); }
// A pattern change moves everyone on it: redraw what shows working hours.
