function patternRequest(method, url, body, done) { return api(method, url, body).then((result) => { state.workingPatterns = result.workingPatterns; done?.(); afterPatternsChanged(); }).catch((error) => showToast(error.message)); }
/* Patterns are shared by the whole company. Before a manager's change reaches people outside their team, a warning
 * names them and must be answered with its buttons (clicking outside it does nothing). Admins aren't asked. */
const managerOnly = () => isManager() && !isAdmin();
function peopleOutsideTeam(patternId) { return state.users.filter((user) => user.patternId === patternId && user.id !== currentUserId && !teamUserIds.includes(user.id)); }
function warnOutsideTeam(message, confirmLabel) { return managerOnly() ? showConfirm(message, confirmLabel, { strict: true }) : Promise.resolve(true); }
function nameList(people) { const names = people.map((user) => user.name || user.email).sort((a, b) => a.localeCompare(b)); return names.length > 6 ? `${names.slice(0, 5).join(', ')} and ${names.length - 5} more` : names.join(', '); }
function savePattern() { const outside = managerOnly() ? peopleOutsideTeam(patternDraft.id) : []; if (!outside.length) return savePatternNow(); return warnOutsideTeam(`${patternDraft.name} is also used by ${plural(outside.length, 'person', 'people')} outside your team (${nameList(outside)}). Your changes will apply to them too.`, 'Save for everyone').then((ok) => { if (ok) savePatternNow(); }); }
function savePatternNow() { const { id, name, days } = patternDraft; for (const day of days.filter((item) => item.mode === 'own')) { const label = WEEKDAYS[day.weekday - 1]; if (!day.start || !day.end || timeToMinutes(day.end) <= timeToMinutes(day.start)) return showToast(`${label}: work must end after it starts`); if (day.breaks.some((brk) => !brk.start || !brk.end || timeToMinutes(brk.end) <= timeToMinutes(brk.start))) return showToast(`${label}: a break must end after it starts`); } return patternRequest('PUT', `/api/working-patterns/${encodeURIComponent(id)}`, { name, days }, () => { setPatternDirty(false); patternDraft = null; showPattern(id); showToast(`${name} saved`); }); }
