function deletePattern() { const saved = state.workingPatterns.find((item) => item.id === patternDraft?.id); if (!saved) return; showConfirm(`Delete the ${saved.name} pattern?`, 'Delete').then((ok) => { if (ok) patternRequest('DELETE', `/api/working-patterns/${encodeURIComponent(saved.id)}`, null, () => { patternDraft = null; setPatternDirty(false); showToast(`${saved.name} deleted`); }); }); }
function makeDefaultPattern() { const saved = state.workingPatterns.find((item) => item.id === patternDraft?.id); if (saved) warnOutsideTeam(`This sets the pattern for everyone added to Time Slide from now on, across the whole company, not just your team. Make ${saved.name} the pattern for new people?`, 'Change for everyone').then((ok) => { if (ok) patternRequest('PUT', `/api/working-patterns/${encodeURIComponent(saved.id)}/default`, null, () => showToast(`People added to Time Slide now start on ${saved.name}`)); }); }
