const infoFilter = { text: '', customer: '', machine: '' };
const infoKeepVisible = new Set();
const infoFiltering = () => Boolean(infoFilter.text.trim() || infoFilter.customer || infoFilter.machine);
function infoSuffixMatches(record, words) { return record.suffixes.filter((suffix) => words.some((word) => `${suffix.letter} ${suffix.description}`.toLowerCase().includes(word))).map((suffix) => suffix.id); }
function infoMatches(record, words) { if (infoKeepVisible.has(record.id)) return true; if (infoFilter.customer && record.customerName !== infoFilter.customer) return false; if (infoFilter.machine && record.machineType !== infoFilter.machine) return false; const text = [record.number, record.customerName, record.machineType, ...record.suffixes.map((suffix) => `${suffix.letter} ${suffix.description}`)].join(' ').toLowerCase(); return words.every((word) => text.includes(word)); }
function renderInfoFilters() { const option = (value, label, chosen) => `<option value="${esc(value)}" ${value === chosen ? 'selected' : ''}>${esc(label)}</option>`; $('#info-customer').innerHTML = option('', 'All customers', infoFilter.customer) + sortNames(state.customers).map((name) => option(name, name, infoFilter.customer)).join(''); $('#info-machine').innerHTML = option('', 'All machine types', infoFilter.machine) + sortNames(state.machineTypes).map((name) => option(name, name, infoFilter.machine)).join(''); }
