  const summary = nC + nS
    ? '<div class="info-import-summary"><p><strong>' + (done ? 'Added' : 'Will add') + ': ' + countOf(nC, 'contract') + ' and ' + countOf(nS, 'suffix', 'suffixes') + '.</strong></p><p class="info-import-muted">' + (nS ? 'Each new suffix ' + (done ? 'has' : 'gets') + " a tile, on no one's dashboard until they add it. " : '') + sameLine + '</p></div>'
    : '<div class="info-import-summary"><p><strong>Nothing new to add.</strong></p><p class="info-import-muted">' + sameLine + ' Sheets read: ' + esc(report.sheets.join(' and ')) + '.</p></div>';
  const table = (head, rows) => '<table><thead><tr>' + head.map((h) => '<th>' + h + '</th>').join('') + '</tr></thead><tbody>' + rows.map((cells) => '<tr>' + cells.map((c) => '<td>' + c + '</td>').join('') + '</tr>').join('') + '</tbody></table>';
  const addList = (title, items, head, cells) => (items.length ? '<details><summary>' + title + ' (' + items.length + ')</summary>' + table(['Row', ...head], items.map((item) => [item.row, ...cells(item).map(esc)])) + '</details>' : '');
  const contractsAdd = addList(done ? 'Contracts added' : 'Contracts to add', report.contracts.add, ['Contract', 'Customer', 'Machine type'], (c) => [c.number, c.customer, c.machine]);
  const suffixesAdd = addList(done ? 'Suffixes added' : 'Suffixes to add', report.suffixes.add, ['Contract', 'Suffix', 'Description'], (s) => [s.number, s.letter, s.description]);
  const listNames = [['customers', 'Customers'], ['machineTypes', 'Machine types'], ['suffixDescriptions', 'Suffix descriptions']].filter(([key]) => lists[key].length);
