async function applyInfoImport() { if (!infoImport) return; const apply = $('#info-import-apply'); apply.disabled = true; try { await saveQueue; const report = await api('POST', '/api/contract-info/import', { dataUrl: infoImport.dataUrl, apply: true }); showInfoImport(report); await reloadState(); showToast('Added ' + countOf(report.contracts.add.length, 'contract') + ' and ' + countOf(report.suffixes.add.length, 'suffix', 'suffixes')); } catch (error) { apply.disabled = false; showToast(error.message); } }
function closeInfoImport() { $('#info-import-modal').classList.add('is-hidden'); infoImport = null; }
function renderContractInfo() { const rows = $('#contract-info-rows'); if (!rows) return; ['#info-download', '#info-import'].forEach((id) => $(id).classList.toggle('is-hidden', !isAdmin())); renderInfoFilters(); /* the lists can change while the screen is open */ const words = infoFilter.text.trim().toLowerCase().split(/\s+/).filter(Boolean); const shown = state.contractInfo.filter((record) => infoMatches(record, words)); const matchedSuffixes = new Set(words.length ? shown.flatMap((record) => infoSuffixMatches(record, words)) : []); $('#contract-info-empty').classList.toggle('is-hidden', shown.length > 0); $('#contract-info-empty').textContent = state.contractInfo.length ? 'No contract matches these filters.' : 'No contract information yet. Add one to get started.'; $('#info-count').textContent = infoFiltering() ? `Showing ${shown.length} of ${state.contractInfo.length}` : ''; $('#info-clear').classList.toggle('is-hidden', !infoFiltering()); rows.innerHTML = shown.map((record) => contractInfoRowTemplate(record.suffixes.some((suffix) => matchedSuffixes.has(suffix.id)) ? { ...record, expanded: true } : record)).join(''); rows.querySelectorAll('[data-suffix-field="letter"]').forEach((input) => input.closest('tr').classList.toggle('is-match', matchedSuffixes.has(input.dataset.suffixId))); rows.querySelectorAll('[data-info-field]').forEach((input) => input.addEventListener('change', () => { const record = state.contractInfo.find((item) => item.id === input.dataset.infoId); record[input.dataset.infoField] = input.value.trim(); saveState(); renderContractInfo(); })); rows.querySelectorAll('[data-suffix-field]').forEach((input) => input.addEventListener('change', () => { const record = state.contractInfo.find((item) => item.id === input.dataset.parentId); const suffix = record?.suffixes.find((item) => item.id === input.dataset.suffixId); if (!suffix) return; let value = input.value.trim(); if (input.dataset.suffixField === 'letter') value = value.toUpperCase(); suffix[input.dataset.suffixField] = value; saveState(); renderContractInfo(); })); rows.querySelectorAll('.expand-suffixes').forEach((button) => button.addEventListener('click', () => toggleContractInfoExpand(button.dataset.infoId))); rows.querySelectorAll('.add-suffix-row').forEach((button) => button.addEventListener('click', () => addSuffixRow(button.dataset.parentId))); rows.querySelectorAll('.remove-suffix-row').forEach((button) => button.addEventListener('click', () => { const suffix = state.contractInfo.find((record) => record.id === button.dataset.parentId)?.suffixes?.find((item) => item.id === button.dataset.suffixId); if (suffix && !canRemoveSuffix(suffix)) { showToast(ADMIN_ONLY_REMOVE); renderContractInfo(); return; } showConfirm('Remove this suffix? Its tile is removed too. If time has been clocked on it, that time is kept in Edit times and Data export.').then((confirmed) => { if (confirmed) removeSuffixRow(button.dataset.parentId, button.dataset.suffixId); }); })); rows.querySelectorAll('.delete-row:not(.remove-suffix-row)').forEach((button) => button.addEventListener('click', () => { const record = state.contractInfo.find((item) => item.id === button.dataset.infoId); if (record && !canRemoveInfo(record)) { showToast(ADMIN_ONLY_REMOVE); renderContractInfo(); return; } showConfirm('Remove this contract information entry? Its tiles are removed too. If time has been clocked on any of them, that time is kept in Edit times and Data export.').then((confirmed) => { if (confirmed) removeContractInfo(button.dataset.infoId); }); })); }
function contractInfoLinkCell(record, field) { return `<div class="link-cell"><input type="url" data-info-id="${esc(record.id)}" data-info-field="${field}" value="${esc(record[field])}" placeholder="https://..."/>${safeUrl(record[field]) ? `<a class="open-link" href="${esc(record[field])}" target="_blank" rel="noopener noreferrer" title="Open link" aria-label="Open link">&#8599;</a>` : ''}</div>`; }
function contractInfoRowTemplate(record) { const parentRow = `<tr class="contract-info-row"><td><input type="text" data-info-id="${esc(record.id)}" data-info-field="number" value="${esc(record.number)}" placeholder="Add a contract number"></td><td><select data-info-id="${esc(record.id)}" data-info-field="machineType">${machineTypeOptionsHtml(record.machineType)}</select></td><td><select class="force-uppercase" data-info-id="${esc(record.id)}" data-info-field="customerName">${customerOptionsHtml(record.customerName)}</select></td><td>${contractInfoLinkCell(record, 'oneDriveLink')}</td><td>${contractInfoLinkCell(record, 'orderConfirmationLink')}</td><td><button class="expand-suffixes ${record.expanded ? 'is-expanded' : ''}" data-info-id="${esc(record.id)}" type="button" title="${record.expanded ? 'Hide suffixes' : 'Show suffixes'}" aria-label="${record.expanded ? 'Hide suffixes' : 'Show suffixes'}"><span class="nav-chevron"></span></button></td><td><button class="delete-row" data-info-id="${esc(record.id)}" type="button" title="${canRemoveInfo(record) ? 'Remove entry' : ADMIN_ONLY_REMOVE}" aria-label="Remove entry"${canRemoveInfo(record) ? '' : ' disabled'}>${X_CIRCLE}</button></td></tr>`; const childRow = `<tr class="suffix-row-container ${record.expanded ? '' : 'is-hidden'}"><td colspan="7">${suffixSubtableTemplate(record)}</td></tr>`; return parentRow + childRow; }
function suffixSubtableTemplate(record) { const suffixRows = record.suffixes.map((suffix) => suffixRowTemplate(record.id, suffix)).join('') || '<tr><td colspan="3" class="suffix-empty">No suffixes yet.</td></tr>'; return `<div class="suffix-subtable"><table><thead><tr><th class="col-narrow">Suffix letter</th><th class="col-suffix-desc"><span class="th-with-action"><span>Suffix description</span><button class="th-add-button" data-heading-add="suffixDescription" type="button" title="Add a suffix description" aria-label="Add a suffix description"><svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.5"/><path d="M8 5v6M5 8h6"/></svg></button></span></th><th class="col-icon"></th></tr></thead><tbody>${suffixRows}</tbody></table><button class="add-button add-suffix-row" data-parent-id="${esc(record.id)}" type="button">+ Add suffix</button></div>`; }
function suffixDescriptionOptionsHtml(selected) { return '<option value="">Select suffix description</option>' + state.suffixDescriptions.map((desc) => `<option value="${esc(desc)}" ${desc === selected ? 'selected' : ''}>${esc(desc)}</option>`).join(''); }
