function toggleContractInfoExpand(id) { const record = state.contractInfo.find((item) => item.id === id); if (!record) return; record.expanded = !record.expanded; saveState(); renderContractInfo(); }
function addSuffixRow(parentId) { const record = state.contractInfo.find((item) => item.id === parentId); if (!record) return; record.suffixes.push({ id: `suffix-${Date.now()}`, letter: '', description: '' }); record.expanded = true; saveState(); renderContractInfo(); }
function removeSuffixRow(parentId, suffixId) { const record = state.contractInfo.find((item) => item.id === parentId); if (!record) return; record.suffixes = record.suffixes.filter((item) => item.id !== suffixId); saveState(); renderContractInfo(); }
function addContractInfo() { const id = `info-${Date.now()}`; infoKeepVisible.add(id); /* stays visible while filtered */ state.contractInfo.push({ id, number: '', machineType: '', customerName: '', oneDriveLink: '', orderConfirmationLink: '', expanded: true, suffixes: [] }); saveState(); renderContractInfo(); }
function removeContractInfo(id) { state.contractInfo = state.contractInfo.filter((item) => item.id !== id); saveState(); renderContractInfo(); showToast('Contract information entry removed'); }
let confirmResolve = null;
let confirmStrict = false; // a strict confirm only closes with its buttons, not by clicking outside it
function showConfirm(message, confirmLabel = 'Confirm', { strict = false } = {}) { return new Promise((resolve) => { confirmResolve = resolve; confirmStrict = strict; $('#confirm-modal-message').textContent = message; $('#confirm-modal-confirm').textContent = confirmLabel; $('#confirm-modal').classList.remove('is-hidden'); }); }
function closeConfirmModal(result) { $('#confirm-modal').classList.add('is-hidden'); if (confirmResolve) { confirmResolve(result); confirmResolve = null; } }
