// Setup -> Data export: a grid of everyone's days (admins) or your own, to check nothing is left uncommitted before exporting.
// Admins export committed days (each day only once -- the server keeps track), undo an export, and email reminders.
let exportOverview = null;
let exportRequest = 0;
const EXPORT_STATUS_TEXT = { uncommitted: 'not committed', committed: 'committed, waiting to export', exported: 'exported', changed: 'changed since export', empty: 'committed, no time' };
const plural = (n, word, many = `${word}s`) => `${n} ${n === 1 ? word : many}`;
function exportRangeFor(kind) { const now = new Date(); const y = now.getFullYear(); const m = now.getMonth(); const sunday = now.getDate() - now.getDay(); /* weeks run Sunday to Saturday */ const ymd = (date) => localDateString(date.getTime()); if (kind === 'this-week') return [ymd(new Date(y, m, sunday)), ymd(new Date(y, m, sunday + 6))]; if (kind === 'last-week') return [ymd(new Date(y, m, sunday - 7)), ymd(new Date(y, m, sunday - 1))]; if (kind === 'last-7-days') return [ymd(new Date(y, m, now.getDate() - 6)), ymd(now)]; /* today and the six days before */ if (kind === 'last-month') return [ymd(new Date(y, m - 1, 1)), ymd(new Date(y, m, 0))]; return [ymd(new Date(y, m, 1)), ymd(new Date(y, m + 1, 0))]; }
function setExportRange(kind) { const [from, to] = exportRangeFor(kind); $('#export-from').value = from; $('#export-to').value = to; loadExportOverview(); }
// Data export opens on the last 7 days (today and the 6 days before); after that it keeps whatever dates were picked.
