/* Light or dark mode: each person's choice, saved on their account (light to begin with). The button beside the profile
 * badge shows the mode it switches to: a moon in light mode, a sun in dark mode. This browser remembers the last one too,
 * only so the next page load starts in it without a flash. */
const THEME_ICONS = {
  dark: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M13.4 9.7A5.6 5.6 0 0 1 6.3 2.6a5.6 5.6 0 1 0 7.1 7.1z"/></svg>',
  light: '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="2.9"/><path d="M8 1.6v1.5M8 12.9v1.5M1.6 8h1.5M12.9 8h1.5M3.5 3.5l1 1M11.5 11.5l1 1M3.5 12.5l1-1M11.5 4.5l1-1"/></svg>',
};
function applyTheme(theme) { const mode = theme === 'dark' ? 'dark' : 'light'; const next = mode === 'dark' ? 'light' : 'dark'; document.documentElement.dataset.theme = mode; try { localStorage.setItem('timeslide-theme', mode); } catch (error) { /* private window: the account still remembers */ } const meta = document.querySelector('meta[name="theme-color"]'); if (meta) meta.content = mode === 'dark' ? '#0f1719' : '#11242a'; const button = $('#theme-toggle'); button.innerHTML = THEME_ICONS[next]; button.title = `Switch to ${next} mode`; button.setAttribute('aria-label', button.title); }
$('#theme-toggle').addEventListener('click', () => { const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark'; applyTheme(next); api('PUT', '/api/me/theme', { theme: next }).catch((error) => showToast(`Could not save the mode: ${error.message}`)); });
