$('#pattern-day').addEventListener('change', (event) => { const day = patternDraft.days[patternDayShown - 1]; const input = event.target; if (input.name === 'pattern-mode') { const monday = patternDraft.days[0]; if (input.value === 'own' && day.mode !== 'own') Object.assign(day, { start: monday.start, end: monday.end, breaks: monday.breaks.map((brk) => ({ start: brk.start, end: brk.end })) }); day.mode = input.value; renderPatternDay(); } else if (input.dataset.patternField) day[input.dataset.patternField] = input.value; else if (input.dataset.breakField) day.breaks[Number(input.dataset.breakIndex)][input.dataset.breakField] = input.value; else return; setPatternDirty(true); renderPatternTabs(); });
